__NUXT_JSONP__("/tr/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"tr",pageTitle:"Statü değişikliği | Mentor Language Institute",pageDescription:"MLI'ya kaydolduğunuz için çok teşekkürler. Bu sayfa ABD'de F1 (öğrenci) VISE'si olmayan ve F1 statüsüne geçmek isteyen kişiler içindir.",title:"Statü değişikliği",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["MLI'ya kaydolduğunuz için çok teşekkürler.\u003Cbr \u002F\u003E Bu sayfa ABD'de F1 (öğrenci) VISE'si olmayan ve F1 statüsüne geçmek isteyen kişiler içindir.","Başvurmak isterseniz lütfen devam edin:"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-tr.png",link:"\u002Ftr\u002Fadmission"}},applicationSteps:{title:"Uygulama adımları",description:["Kesin başvuru adımları, bir kişinin ülkesine, milliyetine, kursa, vize almasına vb. Bağlıdır. Personelimiz, size özel durumunuza göre uygun adımlar konusunda size rehberlik eder."]},needHelp:{title:"Yardıma mı ihtiyacınız var? Bize sorun!",description:["Vize Kuralları ve başvuru adımları mevcut durumunuza göre farklıdır.\u003Cbr \u002F\u003EBaşvuru yapmadan önce açıklamaya ihtiyacınız varsa, lütfen bizimle iletişime geçmekten çekinmeyin. 8 dilde akıcı bir kadromuz var!"]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-tr.png",link:"\u002Ftr\u002Fcontact",title:"Bizimle iletişime geçin",lists:[{campus:"＜WESTWOOD KAMPÜSÜ＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜HOLLYWOOD KAMPÜSÜ＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Ftr",extension:".json",createdAt:"2026-10-22T16:31:28.811Z",updatedAt:"2025-05-26T12:06:27.715Z"}}],fetch:{},mutations:void 0});